1	// THE TERMINAL TRANSITION, IN CODE (#892; docs/PRINCIPLES.md).
2	// A work-item session ends by performing five ordered side effects — comment,
3	// drop `task:agent`, add the outcome label, carry the execution record, close
4	// with the right state reason — on the item it holds, and nothing else: a
5	// converge never writes to another work item (docs/PRINCIPLES.md; #1373 reversed
6	// an earlier attempt). Releasing a dependent a close may have freed is the scheduler run's
7	// job alone. Asking a session to perform these effects from prose is asking for
8	// it at the moment its context is fullest and the remaining work looks like
9	// formality; both of the first two live agentic runs got part of it wrong,
10	// silently, in different ways.
11	//
12	// THIS FILE RUNS IN ONE PLACE: INSIDE A WORK-ITEM SESSION. `queue/instructions.md`
13	// step 6 is its only caller — no workflow invokes it, no module imports it. The
14	// Actions side converges through `executor.mjs`, which owns that path entirely.
15	//
16	// SO EVERY LINE HERE ASSUMES MCP, AND NOTHING HERE MAY REACH THE NETWORK. A session
17	// holds its GitHub access through its own tools; a subprocess it spawns has no route
18	// to them and none to the REST API. This file therefore PLANS a transition and
19	// PRINTS it addressed to those tools — it never performs one. Printing the calls is
20	// the successful outcome, on stdout, exit 0. That is not a fallback: it is the only
21	// path, and it must never read as a failure. A REST executor lived here once and did
22	// (#1491) — a session met its `console.error` before it met the path written for it,
23	// reported that it could not converge, and left the item to the janitor's 3h leash,
24	// which parks a finished run as a human decision. Five sampled items across five
25	// repos were exactly that.
26	//
27	// The split is the same one the executor already draws: THE SESSION SUPPLIES THE
28	// JUDGMENT — which outcome, and the prose of what happened — and the CODE decides
29	// every step of the transition. A session that stops early now leaves an item that
30	// is visibly unconverged, rather than one that looks finished and is not.
31	//
32	// Usage — the item is handed in, because this process cannot read it:
33	//   node converge-item.mjs --issue <n> --outcome <done|approval|action|decision|failure>
34	//                          --summary <text> [--pr <n>]
35	//                          --repo <owner/name> --item-file <path to the issue as JSON>
36	
37	import { readFile } from 'node:fs/promises';
38	import { pathToFileURL } from 'node:url';
39	import { renderTaskExec } from '../items/run-record.mjs';
40	import { actionsEnv } from '../world/actions.mjs';
41	import {
42	  AGENT, TASK_DONE, STATUS_RUNNING_AGENT, isStatus, machineBlockOf,
43	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_FAILURE,
44	  QUEUED_LABEL, IN_REVIEW_LABEL, ORIGIN_LABELS, hasLabel,
45	  parseWorkItemTitle, parseWorkItemBody, spellingsOf, labelNames,
46	  editItemBody, withEndsWhen,
47	} from '../items/work-item.mjs';
48	
49	// What a session may claim, and what each one means for the item. `record` is the
50	// execution-record status, and `null` means no record: an approval park is a run
51	// that SUCCEEDED and left a PR, which the record vocabulary has no word for, and
52	// a fifth status would be stored data every decoder in the fleet must learn.
53	export const OUTCOMES = Object.freeze({
54	  done: { label: TASK_DONE, closes: true, stateReason: 'completed', record: 'success' },
55	  approval: { label: NEEDS_HUMAN_APPROVAL, closes: false, record: null },
56	  action: { label: NEEDS_HUMAN_ACTION, closes: false, record: 'failed' },
57	  decision: { label: NEEDS_HUMAN_DECISION, closes: false, record: 'failed' },
58	  failure: { label: NEEDS_HUMAN_FAILURE, closes: false, record: 'failed' },
59	});
60	
61	export function parseArgs(argv) {
62	  const args = {};
63	  for (let n = 0; n < argv.length; n += 1) {
64	    const m = /^--([a-z-]+)$/.exec(argv[n]);
65	    if (m) { args[m[1]] = argv[n + 1] ?? ''; n += 1; }
66	  }
67	  const issue = Number(args.issue);
68	  if (!Number.isInteger(issue) || issue <= 0) return { error: '--issue must be the work item\'s issue number' };
69	  if (!OUTCOMES[args.outcome]) {
70	    return { error: `--outcome must be one of ${Object.keys(OUTCOMES).join(', ')}, got ${JSON.stringify(args.outcome ?? null)}` };
71	  }
72	  if (!String(args.summary ?? '').trim()) return { error: '--summary must say what happened; it is the item\'s only durable account' };
73	  if (args.outcome === 'approval' && !args.pr) {
74	    return { error: '--pr must name the pull request an approval park is waiting on — a park nobody can act on is not a park' };
75	  }
76	  return {
77	    issue, outcome: args.outcome, summary: args.summary, pr: args.pr ? Number(args.pr) : null,
78	    repo: args.repo || null, itemFile: args['item-file'] || null,
79	  };
80	}
81	
82	// Why an item may NOT be converged by this call. Refusing loudly beats writing a
83	// terminal state onto the wrong issue: this runs from a session, whose whole
84	// notion of which item it holds came from an untrusted fire payload.
85	export function refusal(item, issue) {
86	  if (!item) return `#${issue} could not be read`;
87	  // A marked issue IS its own item (PRINCIPLES.md), so the title test cannot be the
88	  // membership test any more: what says this is one is the machine block adoption
89	  // wrote — never the body's first line, which on a marked issue is a person's prose.
90	  //
91	  // THREE SIGNALS, ANY ONE SUFFICIENT. A membership test gated on the single artifact
92	  // it exists to validate refuses exactly the items that artifact is missing from: an
93	  // issue adopted before the block delimiters existed carries its fields bare, and was
94	  // refused here into a by-hand convergence that dropped half the transition
95	  // (missingbulb/Shepherd#360). The origin label is the independent one — carried for
96	  // life, and platform-write-gated like the block was.
97	  const marked = ORIGIN_LABELS.some((name) => hasLabel(item, name));
98	  if (!parseWorkItemTitle(item.title ?? '') && machineBlockOf(item.body ?? '') === null && !marked) {
99	    return `#${issue} is not a Claudinite work item`;
100	  }
101	  if (item.state !== 'open') return `#${issue} is already closed — it was converged once already`;
102	  if (!isStatus(item, STATUS_RUNNING_AGENT)) {
103	    return `#${issue} is not with an agent (\`${AGENT}\`) — this session does not hold it, so it is not this session's to converge`;
104	  }
105	  return null;
106	}
