116	// The comment one converge writes: the session's account, then the record, so a
117	// reader and a parser both find what they came for in one place.
118	export function convergeComment(item, { summary, pr, record }) {
119	  const rec = recordLine(item, record);
120	  const line = rec ? `\n\n\`\`\`\n${rec}\n\`\`\`` : '';
121	  const waiting = pr ? `\n\nWaiting on a person: merge or close #${pr}, then close this item.` : '';
122	  return `${summary.trim()}${waiting}${line}`;
123	}
