140	  const ops = [{ kind: 'comment', issue: item.number, body: convergeComment(item, { ...plan, record: spec.record }) }];
141	
142	  // The record goes to BOTH sinks, and neither is redundant: the comment above is
143	  // the durable one (Actions logs expire, the item does not), while this printed
144	  // copy lands in the session transcript, which is what the usage fold reads for
145	  // the task-status census.
146	  const rec = recordLine(item, spec.record);
147	  if (rec) ops.push({ kind: 'record', line: rec });
