150	    ops.push({ kind: 'removeLabel', issue: item.number, name: label });
151	  }
152	  // ONE label, on both paths: the outcome IS the status. A park in particular is
153	  // never a pair, so nothing can be half-applied (#1385).
154	  ops.push({ kind: 'addLabel', issue: item.number, name: spec.label });
155	
156	  // THE PARK'S END CONDITION (#1468). The comment above already tells a person to
157	  // merge or close the pull request; this says the same thing where the janitor can
158	  // read it, so the item ends when that happens instead of waiting for someone to
