163	
164	  // SUPERSEDING (PRINCIPLES.md). The executor decided at resolution which of this
165	  // task's earlier pull requests a `supersede_existing_pr` run replaces and stamped
166	  // them on the item; they close only once THIS run's own pull request exists — a
167	  // run that delivered nothing, or broke, leaves them where they were, so a review
168	  // member's pending pull request is never taken away for nothing.
169	  const { supersedes } = parseWorkItemBody(item.body ?? '');
170	  if (plan.pr && (plan.outcome === 'done' || plan.outcome === 'approval')) {
171	    for (const number of supersedes) {
